from typing import List
from collections import defaultdict

class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        ans = nums[0]
        keep = 0
        remove = defaultdict(int)

        for x in nums:
            keep = max(keep, 0) + x
            ans = max(ans, keep)

            if x < 0:
                remove[x] = max(remove[x] + x, keep - x)
                ans = max(ans, remove[x])
            else:
                for key in list(remove.keys()):
                    remove[key] += x
                    ans = max(ans, remove[key])

        return ans
